//! Stable, deterministic versions of the libFuzzer targets (run by
//! `fuzz/quick.sh`). Each property feeds proptest-generated bytes to exactly
//! the same check the fuzz target runs; the committed corpus is replayed too.

use std::path::Path;

use proptest::{collection::vec, prelude::*, test_runner::RngSeed};

fn config(cases: u32) -> ProptestConfig {
    let cases = std::env::var("QUICK_SCALE")
        .ok()
        .and_then(|s| s.parse::<u32>().ok())
        .map_or(cases, |scale| cases * scale);
    ProptestConfig {
        cases,
        rng_seed: RngSeed::Fixed(0x10c1_f022),
        failure_persistence: None,
        max_shrink_iters: 64,
        ..ProptestConfig::default()
    }
}

/// Replay up to `limit` files of the committed libFuzzer corpus.
fn replay(target: &str, limit: usize, run: fn(&[u8])) {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../corpus").join(target);
    let Ok(entries) = std::fs::read_dir(&dir) else {
        return;
    };
    let mut files: Vec<_> = entries.flatten().map(|e| e.path()).collect();
    files.sort();
    for path in files.into_iter().take(limit) {
        let data = std::fs::read(&path).unwrap();
        run(&data);
    }
}

proptest! {
    #![proptest_config(config(256))]
    #[test]
    fn msm_diff(data in vec(any::<u8>(), 0..256)) {
        loki_diff::msm::run(&data);
    }
}

proptest! {
    #![proptest_config(config(256))]
    #[test]
    fn ntt_diff(data in vec(any::<u8>(), 0..256)) {
        loki_diff::ntt::run(&data);
    }
}

#[test]
fn msm_corpus() {
    replay("msm_diff", 64, loki_diff::msm::run);
}

#[test]
fn ntt_corpus() {
    replay("ntt_diff", 64, loki_diff::ntt::run);
}

